package dev.lightstart.mobile.addons

import dev.lightstart.mobile.MobileAddon
import org.json.JSONArray

/** A unit-only add-on that declares a Gradle coordinate the offline build never resolves. */
class GradleAddon : MobileAddon {
    override val families: List<String> = listOf("gradle")

    override fun handle(method: String, args: JSONArray, respond: (Any?) -> Unit, fail: (String) -> Unit): Boolean = false
}
